import{_ as i,A as a,q as e,B as s,aV as t,H as l}from"./chunks/framework.B_e8lQlv.js";const n=JSON.parse('{"title":"规范","description":"","frontmatter":{},"headers":[],"relativePath":"guide/project/standard.md","filePath":"guide/project/standard.md"}');const o=i({name:"guide/project/standard.md"},[["render",function(i,n,o,h,p,d){const r=a("NolebaseGitContributors"),c=a("NolebaseGitChangelog");return e(),s("div",null,[n[0]||(n[0]=t('<h1 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">贡献代码</p><ul><li>如果你想向项目贡献代码，请确保你的代码符合项目的代码规范。</li><li>如果你使用的是 <code>vscode</code>，需要安装以下插件： <ul><li><a href="https://marketplace.visualstudio.com/items?itemName=dbaeumer.vscode-eslint" target="_blank" rel="noreferrer">ESLint</a> - 脚本代码检查</li><li><a href="https://marketplace.visualstudio.com/items?itemName=oxc.oxc-vscode" target="_blank" rel="noreferrer">Oxc</a> - Oxlint / Oxfmt 集成</li><li><a href="https://marketplace.visualstudio.com/items?itemName=streetsidesoftware.code-spell-checker" target="_blank" rel="noreferrer">Code Spell Checker</a> - 单词语法检查</li><li><a href="https://marketplace.visualstudio.com/items?itemName=stylelint.vscode-stylelint" target="_blank" rel="noreferrer">Stylelint</a> - CSS 格式检查</li></ul></li></ul></div><h2 id="作用" tabindex="-1">作用 <a class="header-anchor" href="#作用" aria-label="Permalink to &quot;作用&quot;">​</a></h2><p>具备基本工程素养的同学都会注重编码规范，而代码风格检查（Code Linting，简称 Lint）是保障代码规范一致性的重要手段。</p><p>遵循相应的代码规范有以下好处：</p><ul><li>较少 bug 错误率</li><li>高效的开发效率</li><li>更高的可读性</li></ul><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><p>项目的配置文件位于 <code>internal/lint-configs</code> 下，你可以在这里修改各种 lint 的配置。</p><p>项目内集成了以下几种代码校验工具：</p><ul><li><a href="https://oxc.rs/docs/guide/usage/formatter.html" target="_blank" rel="noreferrer">Oxfmt</a> 用于代码格式化</li><li><a href="https://oxc.rs/docs/guide/usage/linter.html" target="_blank" rel="noreferrer">Oxlint</a> 用于 JavaScript / TypeScript 代码检查</li><li><a href="https://eslint.org/" target="_blank" rel="noreferrer">ESLint</a> 用于 Vue、JSONC、YAML 等规则检查</li><li><a href="https://stylelint.io/" target="_blank" rel="noreferrer">Stylelint</a> 用于 CSS 样式检查</li><li><a href="https://commitlint.js.org/" target="_blank" rel="noreferrer">Commitlint</a> 用于检查 git 提交信息的规范</li><li><a href="https://publint.dev/" target="_blank" rel="noreferrer">Publint</a> 用于检查 npm 包的规范</li><li><a href="https://cspell.org/" target="_blank" rel="noreferrer">Cspell</a> 用于检查拼写错误</li><li><a href="https://github.com/evilmartians/lefthook" target="_blank" rel="noreferrer">lefthook</a> 用于管理 Git hooks，在提交前自动运行代码校验和格式化</li></ul><h2 id="oxfmt" tabindex="-1">Oxfmt <a class="header-anchor" href="#oxfmt" aria-label="Permalink to &quot;Oxfmt&quot;">​</a></h2><p>Oxfmt 用于统一项目代码风格，统一缩进、引号、尾逗号等格式。</p><h3 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oxfmt</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oxfmt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>Oxfmt 的根目录入口文件为 <code>oxfmt.config.ts</code>，其核心配置位于 <code>internal/lint-configs/oxfmt-config</code> 目录下，可以根据项目需求进行修改。</p><h2 id="oxlint" tabindex="-1">Oxlint <a class="header-anchor" href="#oxlint" aria-label="Permalink to &quot;Oxlint&quot;">​</a></h2><p>Oxlint 是当前仓库的主要脚本 lint 工具，用于识别和报告 JavaScript / TypeScript 代码中的问题。</p><h3 id="命令-1" tabindex="-1">命令 <a class="header-anchor" href="#命令-1" aria-label="Permalink to &quot;命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oxlint</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oxlint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span></span></code></pre></div><h3 id="配置-1" tabindex="-1">配置 <a class="header-anchor" href="#配置-1" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>Oxlint 的核心配置位于 <code>internal/lint-configs/oxlint-config</code> 目录下，根目录入口文件为 <code>oxlint.config.ts</code>。</p><h2 id="eslint" tabindex="-1">ESLint <a class="header-anchor" href="#eslint" aria-label="Permalink to &quot;ESLint&quot;">​</a></h2><p>ESLint 用于补充 Vue、JSONC、YAML 等规则检查。</p><h3 id="命令-2" tabindex="-1">命令 <a class="header-anchor" href="#命令-2" aria-label="Permalink to &quot;命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eslint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cache</span></span></code></pre></div><h3 id="配置-2" tabindex="-1">配置 <a class="header-anchor" href="#配置-2" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>ESLint 配置文件为 <code>eslint.config.mjs</code>，其核心配置放在 <code>internal/lint-configs/eslint-config</code> 目录下，可以根据项目需求进行修改。</p><h2 id="stylelint" tabindex="-1">Stylelint <a class="header-anchor" href="#stylelint" aria-label="Permalink to &quot;Stylelint&quot;">​</a></h2><p>Stylelint 用于校验项目内部 CSS 的风格，加上编辑器的自动修复，可以很好的统一项目内部 CSS 风格。</p><h3 id="命令-3" tabindex="-1">命令 <a class="header-anchor" href="#命令-3" aria-label="Permalink to &quot;命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stylelint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;**/*.{vue,css,less,scss}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cache</span></span></code></pre></div><h3 id="配置-3" tabindex="-1">配置 <a class="header-anchor" href="#配置-3" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>Stylelint 配置文件为 <code>stylelint.config.mjs</code>，其核心配置放在 <code>internal/lint-configs/stylelint-config</code> 目录下，可以根据项目需求进行修改。</p><h2 id="commitlint" tabindex="-1">CommitLint <a class="header-anchor" href="#commitlint" aria-label="Permalink to &quot;CommitLint&quot;">​</a></h2><p>在一个团队中，每个人的 git 的 commit 信息都不一样，五花八门，没有一个机制很难保证规范化，如何才能规范化呢？可能你想到的是 git 的 hook 机制，去写 shell 脚本去实现。这当然可以，其实 JavaScript 有一个很好的工具可以实现这个模板，它就是 commitlint（用于校验 git 提交信息规范）。</p><h3 id="配置-4" tabindex="-1">配置 <a class="header-anchor" href="#配置-4" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>CommitLint 配置文件为 <code>.commitlintrc.js</code>，其核心配置放在 <code>internal/lint-configs/commitlint-config</code> 目录下，可以根据项目需求进行修改。</p><h3 id="git-提交规范" tabindex="-1">Git 提交规范 <a class="header-anchor" href="#git-提交规范" aria-label="Permalink to &quot;Git 提交规范&quot;">​</a></h3><p>参考 <a href="https://github.com/conventional-changelog/conventional-changelog/tree/master/packages/conventional-changelog-angular" target="_blank" rel="noreferrer">Angular</a></p><ul><li><code>feat</code> 增加新功能</li><li><code>fix</code> 修复问题 / BUG</li><li><code>style</code> 代码风格相关无影响运行结果的</li><li><code>perf</code> 优化 / 性能提升</li><li><code>refactor</code> 重构</li><li><code>revert</code> 撤销修改</li><li><code>test</code> 测试相关</li><li><code>docs</code> 文档 / 注释</li><li><code>chore</code> 依赖更新 / 脚手架配置修改等</li><li><code>workflow</code> 工作流改进</li><li><code>ci</code> 持续集成</li><li><code>types</code> 类型修改</li></ul><h3 id="关闭-git-提交规范检查" tabindex="-1">关闭 Git 提交规范检查 <a class="header-anchor" href="#关闭-git-提交规范检查" aria-label="Permalink to &quot;关闭 Git 提交规范检查&quot;">​</a></h3><p>如果你想关闭 Git 提交规范检查，有两种方式：</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-obIED" id="tab-cY5LQkR" checked><label data-title="临时关闭" for="tab-cY5LQkR">临时关闭</label><input type="radio" name="group-obIED" id="tab-xVOdBXl"><label data-title="长期关闭" for="tab-xVOdBXl">长期关闭</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;feat: add home page&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-verify</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">commit-msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # commitlint:</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    #   run: pnpm exec commitlint --edit $1</span></span></code></pre></div></div></div><p>如果修改了 <code>lefthook.yml</code>，请重新执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lefthook</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="publint" tabindex="-1">Publint <a class="header-anchor" href="#publint" aria-label="Permalink to &quot;Publint&quot;">​</a></h2><p>Publint 是一个用于检查 npm 包规范的工具，可以检查包的版本号、导出方式以及 ESM 包结构等问题。</p><h3 id="命令-4" tabindex="-1">命令 <a class="header-anchor" href="#命令-4" aria-label="Permalink to &quot;命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publint</span></span></code></pre></div><h2 id="cspell" tabindex="-1">Cspell <a class="header-anchor" href="#cspell" aria-label="Permalink to &quot;Cspell&quot;">​</a></h2><p>Cspell 是一个用于检查拼写错误的工具，可以检查代码中的拼写错误，避免因为拼写错误导致的 bug。</p><h3 id="命令-5" tabindex="-1">命令 <a class="header-anchor" href="#命令-5" aria-label="Permalink to &quot;命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:cspell</span></span></code></pre></div><h3 id="配置-5" tabindex="-1">配置 <a class="header-anchor" href="#配置-5" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>cspell 配置文件为 <code>cspell.json</code>，可以根据项目需求进行修改。</p><h2 id="git-hook" tabindex="-1">Git Hook <a class="header-anchor" href="#git-hook" aria-label="Permalink to &quot;Git Hook&quot;">​</a></h2><p>git hook 一般结合各种 lint，在 git 提交代码的时候进行代码风格校验，如果校验没通过，则不会进行提交。需要开发者自行修改后再次进行提交。</p><h3 id="lefthook" tabindex="-1">lefthook <a class="header-anchor" href="#lefthook" aria-label="Permalink to &quot;lefthook&quot;">​</a></h3><p>有一个问题就是校验会校验全部代码，但是我们只想校验我们自己提交的代码，这个时候就可以使用 lefthook。</p><p>最有效的解决方案就是将 lint 校验放到本地，常见做法是使用 lefthook 在本地提交之前先做一次 lint 校验。</p><p>项目在 <code>lefthook.yml</code> 内部定义了相应的 hooks：</p><ul><li><code>pre-commit</code>: 在提交前运行，用于代码格式化和检查 <ul><li><code>code-workspace</code>: 更新 VSCode 工作区配置</li><li><code>lint-md</code>: 格式化 Markdown 文件</li><li><code>lint-vue</code>: 格式化并检查 Vue 文件</li><li><code>lint-js</code>: 格式化并检查 JavaScript / TypeScript 文件</li><li><code>lint-style</code>: 格式化并检查样式文件</li><li><code>lint-package</code>: 格式化 <code>package.json</code></li><li><code>lint-json</code>: 格式化其他 JSON 文件</li></ul></li><li><code>post-merge</code>: 在合并后运行，用于自动安装依赖 <ul><li><code>install</code>: 运行 <code>pnpm install</code> 安装新依赖</li></ul></li><li><code>commit-msg</code>: 在提交时运行，用于检查提交信息格式 <ul><li><code>commitlint</code>: 使用 commitlint 检查提交信息</li></ul></li></ul><p>当前 hooks 可通过以下命令安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lefthook</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h4 id="如何关闭-lefthook" tabindex="-1">如何关闭 lefthook <a class="header-anchor" href="#如何关闭-lefthook" aria-label="Permalink to &quot;如何关闭 lefthook&quot;">​</a></h4><p>如果你想临时关闭 lefthook，可以使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;feat: add home page&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-verify</span></span></code></pre></div><h4 id="如何修改-lefthook-配置" tabindex="-1">如何修改 lefthook 配置 <a class="header-anchor" href="#如何修改-lefthook-配置" aria-label="Permalink to &quot;如何修改 lefthook 配置&quot;">​</a></h4><p>如果你想修改 lefthook 的配置，可以编辑 <code>lefthook.yml</code> 文件。例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pre-commit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  parallel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    lint-js</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pnpm oxfmt {staged_files} &amp;&amp; pnpm oxlint --fix {staged_files} &amp;&amp; pnpm eslint --cache --fix {staged_files}</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      glob</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;*.{js,jsx,ts,tsx}&#39;</span></span></code></pre></div><p>其中：</p><ul><li><code>parallel</code>: 是否并行执行任务</li><li><code>commands</code>: 定义要执行的任务列表</li><li><code>run</code>: 要执行的命令</li><li><code>glob</code>: 匹配的文件模式</li><li><code>{staged_files}</code>: 表示暂存的文件列表</li></ul>',73)),l(r),l(c)])}]]);export{n as __pageData,o as default};
